package domain

import "time"

// Session is the server-side state associated with one refresh-token family
// member. RefreshTokenHash is intentionally excluded from JSON responses.
type Session struct {
	ID               SessionID     `json:"id"`
	UserID           UserID        `json:"user_id"`
	RefreshTokenHash []byte        `json:"-"`
	ExpiresAt        time.Time     `json:"expires_at"`
	TokenFamilyID    TokenFamilyID `json:"token_family_id"`
	Revoked          bool          `json:"revoked"`
	CreatedAt        time.Time     `json:"created_at"`
}
package domain

import (
	"crypto/rand"
	"crypto/sha256"
	"encoding/base64"
	"errors"
	"strings"
)

// RefreshTokenBytes is the amount of entropy in a refresh token. The token is
// encoded as an opaque URL-safe value for transport to clients.
const RefreshTokenBytes = 32

// NewRefreshToken creates an opaque refresh token. Callers must not persist
// the returned value; it is intended to be given to the client once and then
// replaced by its digest in a repository.
func NewRefreshToken() (string, error) {
	var raw [RefreshTokenBytes]byte
	if _, err := rand.Read(raw[:]); err != nil {
		return "", errors.New("generate refresh token")
	}
	return base64.RawURLEncoding.EncodeToString(raw[:]), nil
}

// GenerateRefreshToken is an explicit alias for NewRefreshToken.
func GenerateRefreshToken() (string, error) { return NewRefreshToken() }

// HashRefreshToken returns the only representation of a refresh token that
// should be retained by application storage.
func HashRefreshToken(token string) []byte {
	digest := sha256.Sum256([]byte(token))
	return append([]byte(nil), digest[:]...)
}

// ValidRefreshToken performs the inexpensive shape check used by repositories
// before hashing a presented credential. It deliberately does not reveal
// whether a token exists.
func ValidRefreshToken(token string) bool {
	if strings.TrimSpace(token) != token || token == "" {
		return false
	}
	raw, err := base64.RawURLEncoding.DecodeString(token)
	return err == nil && len(raw) == RefreshTokenBytes
}
package domain

import (
	"crypto/hmac"
	"crypto/rand"
	"crypto/sha256"
	"crypto/subtle"
	"encoding/base64"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"strings"
	"time"
)

// AccessTokenClaims is the payload carried by an access token. Times use the
// NumericDate representation required by JWT (seconds since Unix epoch).
type AccessTokenClaims struct {
	Subject string `json:"sub"`
	Email   string `json:"email"`
	Issuer  string `json:"iss"`
	Issued  int64  `json:"iat"`
	Expiry  int64  `json:"exp"`
	JTI     string `json:"jti"`
}

type accessTokenHeader struct {
	Algorithm string `json:"alg"`
	Type      string `json:"typ"`
}

// AccessTokenValidator validates access tokens issued by AccessTokenIssuer.
// Clock is injected to make expiry checks deterministic for callers and tests.
type AccessTokenValidator struct {
	Secret []byte
	Issuer string
	Clock  Clock
}

// Validate checks the compact JWT format, the signing algorithm, the HMAC
// signature, the issuer, and the required time and identity claims.
func (v AccessTokenValidator) Validate(token string) (AccessTokenClaims, error) {
	var empty AccessTokenClaims
	if len(v.Secret) < 32 || strings.TrimSpace(v.Issuer) == "" {
		return empty, errors.New("invalid access token")
	}
	parts := strings.Split(token, ".")
	if len(parts) != 3 || parts[0] == "" || parts[1] == "" || parts[2] == "" {
		return empty, errors.New("invalid access token")
	}
	codec := base64.RawURLEncoding
	headerBytes, err := codec.DecodeString(parts[0])
	if err != nil {
		return empty, errors.New("invalid access token")
	}
	var header accessTokenHeader
	if err := decodeStrictJSON(headerBytes, &header); err != nil ||
		header.Algorithm != "HS256" || header.Type != "JWT" {
		return empty, errors.New("invalid access token")
	}

	suppliedSignature, err := codec.DecodeString(parts[2])
	if err != nil || len(suppliedSignature) != sha256.Size {
		return empty, errors.New("invalid access token")
	}
	mac := hmac.New(sha256.New, v.Secret)
	_, _ = mac.Write([]byte(parts[0] + "." + parts[1]))
	if subtle.ConstantTimeCompare(mac.Sum(nil), suppliedSignature) != 1 {
		return empty, errors.New("invalid access token")
	}

	payload, err := codec.DecodeString(parts[1])
	if err != nil {
		return empty, errors.New("invalid access token")
	}
	var claims AccessTokenClaims
	if err := decodeStrictJSON(payload, &claims); err != nil ||
		strings.TrimSpace(claims.Subject) == "" || strings.TrimSpace(claims.Email) == "" ||
		strings.TrimSpace(claims.Issuer) == "" || strings.TrimSpace(claims.JTI) == "" ||
		claims.Issuer != v.Issuer || claims.Issued <= 0 || claims.Expiry <= 0 ||
		claims.Expiry <= claims.Issued {
		return empty, errors.New("invalid access token")
	}
	if _, err := ValidateEmail(claims.Email); err != nil {
		return empty, errors.New("invalid access token")
	}
	clock := v.Clock
	if clock == nil {
		clock = RealClock{}
	}
	if claims.Expiry <= clock.Now().UTC().Unix() {
		return empty, errors.New("invalid access token")
	}
	return claims, nil
}

// ValidateAccessToken is a convenience wrapper for callers that do not need
// to retain a validator instance.
func ValidateAccessToken(token, issuer string, now time.Time, secret []byte) (AccessTokenClaims, error) {
	return (AccessTokenValidator{
		Secret: secret,
		Issuer: issuer,
		Clock:  ClockFunc(func() time.Time { return now }),
	}).Validate(token)
}

func decodeStrictJSON(data []byte, destination any) error {
	decoder := json.NewDecoder(strings.NewReader(string(data)))
	decoder.DisallowUnknownFields()
	if err := decoder.Decode(destination); err != nil {
		return err
	}
	var extra any
	if err := decoder.Decode(&extra); !errors.Is(err, io.EOF) {
		return errors.New("invalid JSON")
	}
	return nil
}

// AccessTokenIssuer creates JWT-compatible HS256 access tokens.
// The issuer's clock is injected so token lifetimes can be deterministic in
// callers and tests without coupling this code to the global clock.
type AccessTokenIssuer struct {
	Secret []byte
	Issuer string
	TTL    time.Duration
	Clock  Clock
}

// Issue creates a signed access token for subject and email.
func (i AccessTokenIssuer) Issue(subject, email string) (string, AccessTokenClaims, error) {
	if len(i.Secret) < 32 {
		return "", AccessTokenClaims{}, errors.New("HMAC secret must be at least 32 bytes")
	}
	if strings.TrimSpace(i.Issuer) == "" {
		return "", AccessTokenClaims{}, errors.New("issuer must not be empty")
	}
	if strings.TrimSpace(subject) == "" || strings.TrimSpace(email) == "" {
		return "", AccessTokenClaims{}, errors.New("subject and email must not be empty")
	}
	if i.TTL <= 0 {
		return "", AccessTokenClaims{}, errors.New("access token TTL must be positive")
	}
	clock := i.Clock
	if clock == nil {
		clock = RealClock{}
	}
	now := clock.Now().UTC().Truncate(time.Second)
	expiry := now.Add(i.TTL).Unix()
	if expiry <= now.Unix() {
		return "", AccessTokenClaims{}, errors.New("access token TTL must be at least one second")
	}

	jti, err := randomJTI()
	if err != nil {
		return "", AccessTokenClaims{}, fmt.Errorf("generate access token id: %w", err)
	}
	claims := AccessTokenClaims{
		Subject: subject,
		Email:   email,
		Issuer:  i.Issuer,
		Issued:  now.Unix(),
		Expiry:  expiry,
		JTI:     jti,
	}
	header, err := json.Marshal(accessTokenHeader{Algorithm: "HS256", Type: "JWT"})
	if err != nil {
		return "", AccessTokenClaims{}, fmt.Errorf("encode access token header: %w", err)
	}
	payload, err := json.Marshal(claims)
	if err != nil {
		return "", AccessTokenClaims{}, fmt.Errorf("encode access token claims: %w", err)
	}
	codec := base64.RawURLEncoding
	unsigned := codec.EncodeToString(header) + "." + codec.EncodeToString(payload)
	mac := hmac.New(sha256.New, i.Secret)
	_, _ = mac.Write([]byte(unsigned))
	token := unsigned + "." + codec.EncodeToString(mac.Sum(nil))
	return token, claims, nil
}

// CreateAccessToken is a convenience wrapper for issuing an access token.
func CreateAccessToken(subject, email, issuer string, now time.Time, ttl time.Duration, secret []byte) (string, error) {
	token, _, err := (AccessTokenIssuer{
		Secret: secret,
		Issuer: issuer,
		TTL:    ttl,
		Clock:  ClockFunc(func() time.Time { return now }),
	}).Issue(subject, email)
	return token, err
}

func randomJTI() (string, error) {
	var value [16]byte
	if _, err := rand.Read(value[:]); err != nil {
		return "", err
	}
	return base64.RawURLEncoding.EncodeToString(value[:]), nil
}
package repository

import (
	"bytes"
	"sync"

	"benchmark.local/iam/internal/domain"
)

// SessionRepository is a concurrency-safe in-memory store. The token index
// contains SHA-256 digests only; the clear refresh token is never retained.
type SessionRepository struct {
	mu       sync.RWMutex
	sessions map[domain.SessionID]domain.Session
	byToken  map[[32]byte]domain.SessionID
}

func NewSessionRepository() *SessionRepository {
	return &SessionRepository{
		sessions: make(map[domain.SessionID]domain.Session),
		byToken:  make(map[[32]byte]domain.SessionID),
	}
}

// Create stores a session and hashes refreshToken before it enters the
// repository. A session ID, user, family, and expiry are required.
func (r *SessionRepository) Create(session domain.Session, refreshToken string) error {
	if session.ID == "" || session.UserID == "" || session.TokenFamilyID == "" ||
		session.ExpiresAt.IsZero() ||
		!domain.ValidRefreshToken(refreshToken) {
		return domain.NewInvalid("invalid session")
	}
	digest := domain.HashRefreshToken(refreshToken)
	var key [32]byte
	copy(key[:], digest)
	session.RefreshTokenHash = digest
	r.mu.Lock()
	defer r.mu.Unlock()
	if _, exists := r.sessions[session.ID]; exists {
		return domain.NewConflict("session already exists")
	}
	if _, exists := r.byToken[key]; exists {
		return domain.NewConflict("refresh token already exists")
	}
	r.sessions[session.ID] = cloneSession(session)
	r.byToken[key] = session.ID
	return nil
}

// CreateSession is a descriptive alias for Create.
func (r *SessionRepository) CreateSession(session domain.Session, refreshToken string) error {
	return r.Create(session, refreshToken)
}

// GetByID returns a detached session, including revoked sessions so callers
// can distinguish rotation replay from an unknown token.
func (r *SessionRepository) GetByID(id domain.SessionID) (domain.Session, error) {
	r.mu.RLock()
	session, ok := r.sessions[id]
	r.mu.RUnlock()
	if !ok {
		return domain.Session{}, domain.NewNotFound("session not found")
	}
	return cloneSession(session), nil
}

// GetByRefreshToken finds a session by hashing the presented opaque value.
func (r *SessionRepository) GetByRefreshToken(refreshToken string) (domain.Session, error) {
	if !domain.ValidRefreshToken(refreshToken) {
		return domain.Session{}, domain.NewNotFound("session not found")
	}
	digest := domain.HashRefreshToken(refreshToken)
	var key [32]byte
	copy(key[:], digest)
	r.mu.RLock()
	id, ok := r.byToken[key]
	session := r.sessions[id]
	r.mu.RUnlock()
	if !ok {
		return domain.Session{}, domain.NewNotFound("session not found")
	}
	return cloneSession(session), nil
}

// GetByToken is a concise alias for GetByRefreshToken.
func (r *SessionRepository) GetByToken(refreshToken string) (domain.Session, error) {
	return r.GetByRefreshToken(refreshToken)
}

func (r *SessionRepository) Revoke(id domain.SessionID) error {
	r.mu.Lock()
	defer r.mu.Unlock()
	session, ok := r.sessions[id]
	if !ok {
		return domain.NewNotFound("session not found")
	}
	session.Revoked = true
	r.sessions[id] = session
	return nil
}

// RevokeFamily revokes every session belonging to the token family.
func (r *SessionRepository) RevokeFamily(family domain.TokenFamilyID) int {
	if family == "" {
		return 0
	}
	r.mu.Lock()
	defer r.mu.Unlock()
	count := 0
	for id, session := range r.sessions {
		if session.TokenFamilyID == family && !session.Revoked {
			session.Revoked = true
			r.sessions[id] = session
			count++
		}
	}
	return count
}

func (r *SessionRepository) ListByUser(userID domain.UserID) []domain.Session {
	r.mu.RLock()
	result := make([]domain.Session, 0)
	for _, session := range r.sessions {
		if session.UserID == userID {
			result = append(result, cloneSession(session))
		}
	}
	r.mu.RUnlock()
	return result
}

func cloneSession(session domain.Session) domain.Session {
	session.RefreshTokenHash = bytes.Clone(session.RefreshTokenHash)
	return session
}
// Package app wires process configuration to the HTTP server dependencies.
package app

import (
	"context"
	"crypto/rand"
	"encoding/hex"
	"encoding/json"
	"errors"
	"io"
	"net/http"
	"strings"

	"benchmark.local/iam/internal/config"
	"benchmark.local/iam/internal/domain"
	"benchmark.local/iam/internal/repository"
)

// App is the top-level HTTP application. Domain dependencies are added here as
// they are introduced, keeping construction in one place.
type App struct {
	cfg     config.Config
	handler http.Handler
	users   *repository.UserRepository
	clock   domain.Clock
}

const maxJSONBodySize int64 = 1 << 20

// New constructs an application from validated configuration.
func New(cfg config.Config) (*App, error) {
	if err := cfg.Validate(); err != nil {
		return nil, err
	}
	mux := http.NewServeMux()
	mux.HandleFunc("GET /healthz", health)
	mux.HandleFunc("GET /readyz", health)
	users := repository.NewUserRepository()
	application := &App{cfg: cfg, users: users, clock: domain.RealClock{}}
	mux.HandleFunc("POST /v1/register", application.register)
	mux.HandleFunc("POST /v1/login", application.login)
	mux.Handle("GET /v1/me", application.bearerMiddleware(http.HandlerFunc(application.me)))
	application.handler = withRequestID(mux)
	return application, nil
}

// Handler returns the HTTP handler used by cmd/iamd.
func (a *App) Handler() http.Handler { return a.handler }

// Server returns a configured net/http server.
func (a *App) Server() *http.Server {
	return &http.Server{
		Addr:         a.cfg.Address,
		Handler:      a.handler,
		ReadTimeout:  a.cfg.ReadTimeout,
		WriteTimeout: a.cfg.WriteTimeout,
		IdleTimeout:  a.cfg.IdleTimeout,
	}
}

func health(w http.ResponseWriter, _ *http.Request) {
	writeJSON(w, http.StatusOK, dataEnvelope{Data: map[string]string{"status": "ok"}})
}

type registerRequest struct {
	Email    string `json:"email"`
	Password string `json:"password"`
}

type loginResponse struct {
	AccessToken string `json:"access_token"`
	TokenType   string `json:"token_type"`
	ExpiresIn   int64  `json:"expires_in"`
}

type dataEnvelope struct {
	Data any `json:"data"`
}

type errorEnvelope struct {
	Error errorBody `json:"error"`
}

type errorBody struct {
	Code      string `json:"code"`
	Message   string `json:"message"`
	RequestID string `json:"request_id"`
}

func (a *App) register(w http.ResponseWriter, r *http.Request) {
	requestID := requestID(r)
	w.Header().Set("X-Request-ID", requestID)
	var input registerRequest
	if err := decodeJSON(r, &input); err != nil {
		writeError(w, http.StatusBadRequest, "invalid_request", "invalid request body", requestID)
		return
	}
	email, err := domain.ValidateEmail(input.Email)
	if err != nil {
		writeError(w, http.StatusBadRequest, "invalid_request", "invalid email", requestID)
		return
	}
	material, err := domain.HashPassword(input.Password)
	if err != nil {
		writeError(w, http.StatusBadRequest, "invalid_request", err.Error(), requestID)
		return
	}
	id, err := domain.NewUserID()
	if err != nil {
		writeError(w, http.StatusInternalServerError, "internal_error", "internal server error", requestID)
		return
	}
	now := a.clock.Now().UTC()
	user := domain.User{
		ID:                     id,
		Email:                  email,
		EmailVerificationState: domain.EmailVerificationPending,
		PasswordMaterial:       material,
		CreatedAt:              now,
		UpdatedAt:              now,
	}
	if err := a.users.Create(user); err != nil {
		if domain.IsKind(err, domain.ErrConflict) {
			writeError(w, http.StatusConflict, "conflict", "email already exists", requestID)
			return
		}
		writeError(w, http.StatusInternalServerError, "internal_error", "internal server error", requestID)
		return
	}
	writeJSON(w, http.StatusCreated, dataEnvelope{Data: user.PublicProfile()})
}

// login authenticates an account and issues a short-lived access token. Every
// credential failure uses the same response, including an unknown or invalid
// email, so callers cannot use this endpoint to enumerate accounts.
func (a *App) login(w http.ResponseWriter, r *http.Request) {
	requestID := requestID(r)
	w.Header().Set("X-Request-ID", requestID)
	var input registerRequest
	if err := decodeJSON(r, &input); err != nil {
		writeError(w, http.StatusBadRequest, "invalid_request", "invalid request body", requestID)
		return
	}

	email, err := domain.ValidateEmail(input.Email)
	if err != nil {
		writeUnauthorized(w, requestID)
		return
	}
	user, err := a.users.GetByEmail(email)
	if err != nil || !domain.VerifyPassword(input.Password, user.PasswordMaterial) {
		writeUnauthorized(w, requestID)
		return
	}

	issuer := domain.AccessTokenIssuer{
		Secret: a.cfg.HMACSecret,
		Issuer: a.cfg.Issuer,
		TTL:    a.cfg.AccessTTL,
		Clock:  a.clock,
	}
	token, claims, err := issuer.Issue(string(user.ID), user.Email)
	if err != nil {
		writeError(w, http.StatusInternalServerError, "internal_error", "internal server error", requestID)
		return
	}
	writeJSON(w, http.StatusOK, dataEnvelope{Data: loginResponse{
		AccessToken: token,
		TokenType:   "Bearer",
		ExpiresIn:   claims.Expiry - claims.Issued,
	}})
}

type accessTokenClaimsContextKey struct{}

// ClaimsFromContext returns the claims attached by bearerMiddleware. It is
// intentionally the only way handlers need to know how authentication state
// is represented in a request context.
func ClaimsFromContext(ctx context.Context) (domain.AccessTokenClaims, bool) {
	claims, ok := ctx.Value(accessTokenClaimsContextKey{}).(domain.AccessTokenClaims)
	return claims, ok
}

func (a *App) bearerMiddleware(next http.Handler) http.Handler {
	validator := domain.AccessTokenValidator{
		Secret: a.cfg.HMACSecret,
		Issuer: a.cfg.Issuer,
		Clock:  a.clock,
	}
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		authorization := strings.TrimSpace(r.Header.Get("Authorization"))
		parts := strings.Fields(authorization)
		if len(parts) != 2 || !strings.EqualFold(parts[0], "Bearer") {
			writeError(w, http.StatusUnauthorized, "unauthorized", "invalid access token", requestID(r))
			return
		}
		claims, err := validator.Validate(parts[1])
		if err != nil {
			writeError(w, http.StatusUnauthorized, "unauthorized", "invalid access token", requestID(r))
			return
		}
		ctx := context.WithValue(r.Context(), accessTokenClaimsContextKey{}, claims)
		next.ServeHTTP(w, r.WithContext(ctx))
	})
}

func (a *App) me(w http.ResponseWriter, r *http.Request) {
	claims, ok := ClaimsFromContext(r.Context())
	if !ok {
		writeError(w, http.StatusUnauthorized, "unauthorized", "invalid access token", requestID(r))
		return
	}
	user, err := a.users.GetByID(domain.UserID(claims.Subject))
	if err != nil {
		writeError(w, http.StatusUnauthorized, "unauthorized", "invalid access token", requestID(r))
		return
	}
	writeJSON(w, http.StatusOK, dataEnvelope{Data: user.PublicProfile()})
}

func writeUnauthorized(w http.ResponseWriter, requestID string) {
	writeError(w, http.StatusUnauthorized, "unauthorized", "invalid credentials", requestID)
}

func decodeJSON(r *http.Request, destination any) error {
	limited := &countingReader{reader: io.LimitReader(r.Body, maxJSONBodySize+1)}
	decoder := json.NewDecoder(limited)
	decoder.DisallowUnknownFields()
	if err := decoder.Decode(destination); err != nil {
		return err
	}
	if limited.count > maxJSONBodySize {
		return errors.New("request body too large")
	}
	var extra any
	if err := decoder.Decode(&extra); !errors.Is(err, io.EOF) {
		if err == nil {
			return errors.New("multiple JSON values")
		}
		return err
	}
	if limited.count > maxJSONBodySize {
		return errors.New("request body too large")
	}
	return nil
}

type countingReader struct {
	reader io.Reader
	count  int64
}

func (r *countingReader) Read(p []byte) (int, error) {
	n, err := r.reader.Read(p)
	r.count += int64(n)
	return n, err
}

func withRequestID(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("X-Request-ID", requestID(r))
		next.ServeHTTP(w, r)
	})
}

func requestID(r *http.Request) string {
	if value := strings.TrimSpace(r.Header.Get("X-Request-ID")); value != "" {
		return value
	}
	var raw [16]byte
	if _, err := rand.Read(raw[:]); err == nil {
		return hex.EncodeToString(raw[:])
	}
	return "unknown"
}

func writeJSON(w http.ResponseWriter, status int, value any) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(value)
}

func writeError(w http.ResponseWriter, status int, code, message, requestID string) {
	writeJSON(w, status, errorEnvelope{Error: errorBody{Code: code, Message: message, RequestID: requestID}})
}

// Package config contains the process configuration and its validation.
package config

import (
	"crypto/rand"
	"errors"
	"fmt"
	"os"
	"strconv"
	"strings"
	"time"
)

const (
	defaultAddress       = ":8080"
	defaultIssuer        = "iam"
	defaultAccessTTL     = 15 * time.Minute
	defaultRefreshTTL    = 30 * 24 * time.Hour
	defaultReadTimeout   = 10 * time.Second
	defaultWriteTimeout  = 10 * time.Second
	defaultIdleTimeout   = 60 * time.Second
	defaultShutdownGrace = 10 * time.Second
)

// Config is the immutable configuration used to construct the service.
// HMACSecret is kept as bytes so callers do not need to repeatedly convert it.
type Config struct {
	Address         string
	Issuer          string
	HMACSecret      []byte
	AccessTTL       time.Duration
	RefreshTTL      time.Duration
	ReadTimeout     time.Duration
	WriteTimeout    time.Duration
	IdleTimeout     time.Duration
	ShutdownGrace   time.Duration
	LoginRateLimit  int
	APIKeyRateLimit int
}

// Load reads IAM_* environment variables and validates the resulting config.
// IAM_HMAC_SECRET is mandatory and must contain at least 32 bytes.
func Load() (Config, error) {
	secret := os.Getenv("IAM_HMAC_SECRET")
	if secret == "" {
		return Config{}, errors.New("IAM_HMAC_SECRET is required")
	}

	c := Config{
		Address:         envString("IAM_ADDRESS", defaultAddress),
		Issuer:          envString("IAM_ISSUER", defaultIssuer),
		HMACSecret:      []byte(secret),
		AccessTTL:       envDuration("IAM_ACCESS_TTL", defaultAccessTTL),
		RefreshTTL:      envDuration("IAM_REFRESH_TTL", defaultRefreshTTL),
		ReadTimeout:     envDuration("IAM_READ_TIMEOUT", defaultReadTimeout),
		WriteTimeout:    envDuration("IAM_WRITE_TIMEOUT", defaultWriteTimeout),
		IdleTimeout:     envDuration("IAM_IDLE_TIMEOUT", defaultIdleTimeout),
		ShutdownGrace:   envDuration("IAM_SHUTDOWN_GRACE", defaultShutdownGrace),
		LoginRateLimit:  envInt("IAM_LOGIN_RATE_LIMIT", 10),
		APIKeyRateLimit: envInt("IAM_APIKEY_RATE_LIMIT", 60),
	}
	if err := c.Validate(); err != nil {
		return Config{}, err
	}
	return c, nil
}

// Validate rejects unsafe or unusable runtime settings.
func (c Config) Validate() error {
	if strings.TrimSpace(c.Address) == "" {
		return errors.New("address must not be empty")
	}
	if strings.TrimSpace(c.Issuer) == "" {
		return errors.New("issuer must not be empty")
	}
	if len(c.HMACSecret) < 32 {
		return errors.New("HMAC secret must be at least 32 bytes")
	}
	for name, value := range map[string]time.Duration{
		"access TTL": c.AccessTTL, "refresh TTL": c.RefreshTTL,
		"read timeout": c.ReadTimeout, "write timeout": c.WriteTimeout,
		"idle timeout": c.IdleTimeout, "shutdown grace": c.ShutdownGrace,
	} {
		if value <= 0 {
			return fmt.Errorf("%s must be positive", name)
		}
	}
	if c.RefreshTTL < c.AccessTTL {
		return errors.New("refresh TTL must not be shorter than access TTL")
	}
	if c.LoginRateLimit <= 0 || c.APIKeyRateLimit <= 0 {
		return errors.New("rate limits must be positive")
	}
	return nil
}

// GenerateSecret returns a cryptographically random secret suitable for local setup.
func GenerateSecret(size int) ([]byte, error) {
	if size < 32 {
		return nil, errors.New("secret size must be at least 32 bytes")
	}
	b := make([]byte, size)
	if _, err := rand.Read(b); err != nil {
		return nil, fmt.Errorf("generate secret: %w", err)
	}
	return b, nil
}

func envString(key, fallback string) string {
	if value := strings.TrimSpace(os.Getenv(key)); value != "" {
		return value
	}
	return fallback
}

func envDuration(key string, fallback time.Duration) time.Duration {
	value := strings.TrimSpace(os.Getenv(key))
	if value == "" {
		return fallback
	}
	duration, err := time.ParseDuration(value)
	if err != nil {
		return -1
	}
	return duration
}

func envInt(key string, fallback int) int {
	value := strings.TrimSpace(os.Getenv(key))
	if value == "" {
		return fallback
	}
	result, err := strconv.Atoi(value)
	if err != nil {
		return -1
	}
	return result
}
// Package domain contains shared IAM domain primitives.
package domain

import (
	"crypto/rand"
	"encoding/hex"
	"errors"
	"fmt"
)

// ID is the common representation of an entity identifier. Values are UUID
// version 4 strings, generated with crypto/rand.
type ID string

type UserID ID
type OrganizationID ID
type SessionID ID
type InviteID ID
type RoleID ID
type APIKeyID ID
type TokenFamilyID ID

// NewID returns a new random UUID version 4 identifier.
func NewID() (ID, error) {
	var value [16]byte
	if _, err := rand.Read(value[:]); err != nil {
		return "", fmt.Errorf("generate id: %w", err)
	}
	value[6] = (value[6] & 0x0f) | 0x40
	value[8] = (value[8] & 0x3f) | 0x80
	encoded := make([]byte, 36)
	hex.Encode(encoded[0:8], value[0:4])
	hex.Encode(encoded[9:13], value[4:6])
	hex.Encode(encoded[14:18], value[6:8])
	hex.Encode(encoded[19:23], value[8:10])
	hex.Encode(encoded[24:36], value[10:16])
	encoded[8], encoded[13], encoded[18], encoded[23] = '-', '-', '-', '-'
	return ID(encoded), nil
}

func newTypedID[T ~string](newValue func() (ID, error)) (T, error) {
	id, err := newValue()
	return T(id), err
}

func NewUserID() (UserID, error) { return newTypedID[UserID](NewID) }

func NewOrganizationID() (OrganizationID, error) { return newTypedID[OrganizationID](NewID) }

func NewSessionID() (SessionID, error) { return newTypedID[SessionID](NewID) }

func NewInviteID() (InviteID, error) { return newTypedID[InviteID](NewID) }

func NewRoleID() (RoleID, error) { return newTypedID[RoleID](NewID) }

func NewAPIKeyID() (APIKeyID, error) { return newTypedID[APIKeyID](NewID) }

func NewTokenFamilyID() (TokenFamilyID, error) { return newTypedID[TokenFamilyID](NewID) }

// ParseID validates the textual UUID representation before converting it to ID.
func ParseID(value string) (ID, error) {
	if len(value) != 36 || value[8] != '-' || value[13] != '-' || value[18] != '-' || value[23] != '-' {
		return "", errors.New("invalid id")
	}
	var raw [16]byte
	if _, err := hex.Decode(raw[:4], []byte(value[0:8])); err != nil {
		return "", errors.New("invalid id")
	}
	if _, err := hex.Decode(raw[4:6], []byte(value[9:13])); err != nil {
		return "", errors.New("invalid id")
	}
	if _, err := hex.Decode(raw[6:8], []byte(value[14:18])); err != nil {
		return "", errors.New("invalid id")
	}
	if _, err := hex.Decode(raw[8:10], []byte(value[19:23])); err != nil {
		return "", errors.New("invalid id")
	}
	if _, err := hex.Decode(raw[10:16], []byte(value[24:36])); err != nil {
		return "", errors.New("invalid id")
	}
	return ID(value), nil
}
package domain

import "time"

// EmailVerificationState describes the state of a user's email address.
// Keeping this state explicit avoids inferring verification from the presence
// or absence of unrelated user data.
type EmailVerificationState string

const (
	EmailVerificationPending  EmailVerificationState = "pending"
	EmailVerificationVerified EmailVerificationState = "verified"
)

// PasswordMaterial contains only the derived password material needed for
// password verification. It deliberately has no JSON representation: this
// type must not leak through API responses, logs, or other JSON envelopes.
type PasswordMaterial struct {
	Salt       []byte
	Hash       []byte
	Iterations uint32
}

// MarshalJSON prevents accidental serialization even when PasswordMaterial is
// marshaled directly rather than as part of User.
func (PasswordMaterial) MarshalJSON() ([]byte, error) { return []byte("{}"), nil }

// User is the private domain representation of an account. PasswordMaterial
// is kept separate from the fields exposed by PublicUserProfile.
type User struct {
	ID                     UserID                 `json:"id"`
	Email                  string                 `json:"email"`
	EmailVerified          bool                   `json:"email_verified"`
	EmailVerificationState EmailVerificationState `json:"email_verification_state"`
	PasswordMaterial       PasswordMaterial       `json:"-"`
	CreatedAt              time.Time              `json:"created_at"`
	UpdatedAt              time.Time              `json:"updated_at"`
}

// PublicUserProfile is the safe representation of a user for API responses.
// It contains account identity and verification state, but no password data.
type PublicUserProfile struct {
	ID                     UserID                 `json:"id"`
	Email                  string                 `json:"email"`
	EmailVerified          bool                   `json:"email_verified"`
	EmailVerificationState EmailVerificationState `json:"email_verification_state"`
	CreatedAt              time.Time              `json:"created_at"`
}

// PublicProfile returns the user data that may be sent to a client.
func (u User) PublicProfile() PublicUserProfile {
	return PublicUserProfile{
		ID:                     u.ID,
		Email:                  u.Email,
		EmailVerified:          u.EmailVerified,
		EmailVerificationState: u.EmailVerificationState,
		CreatedAt:              u.CreatedAt,
	}
}
package main

import (
	"context"
	"errors"
	"log/slog"
	"os"
	"os/signal"
	"syscall"

	"benchmark.local/iam/internal/app"
	"benchmark.local/iam/internal/config"
)

func main() {
	cfg, err := config.Load()
	if err != nil {
		slog.Error("invalid configuration", "error", err)
		return
	}
	application, err := app.New(cfg)
	if err != nil {
		slog.Error("initialize application", "error", err)
		return
	}
	server := application.Server()
	ctx, stop := signal.NotifyContext(context.Background(), syscall.SIGINT, syscall.SIGTERM)
	defer stop()

	go func() {
		if err := server.ListenAndServe(); err != nil && !errors.Is(err, context.Canceled) {
			slog.Error("HTTP server stopped", "error", err)
		}
	}()
	<-ctx.Done()
	shutdownCtx, cancel := context.WithTimeout(context.Background(), cfg.ShutdownGrace)
	defer cancel()
	if err := server.Shutdown(shutdownCtx); err != nil {
		slog.Error("graceful shutdown failed", "error", err)
		os.Exit(1)
	}
}
package domain

import "errors"

var (
	ErrNotFound     = errors.New("not found")
	ErrConflict     = errors.New("conflict")
	ErrInvalid      = errors.New("invalid")
	ErrUnauthorized = errors.New("unauthorized")
)

// Error preserves a stable domain error category while allowing callers to
// attach a safe, human-readable message and an underlying cause.
type Error struct {
	Kind    error
	Message string
	Cause   error
}

func (e *Error) Error() string {
	if e.Message != "" {
		return e.Message
	}
	return e.Kind.Error()
}

func (e *Error) Unwrap() error { return e.Cause }

func (e *Error) Is(target error) bool { return target == e.Kind }

func NewNotFound(message string) error     { return newError(ErrNotFound, message) }
func NewConflict(message string) error     { return newError(ErrConflict, message) }
func NewInvalid(message string) error      { return newError(ErrInvalid, message) }
func NewUnauthorized(message string) error { return newError(ErrUnauthorized, message) }

func Wrap(kind, message string, cause error) error {
	category := ErrInvalid
	switch kind {
	case "not_found":
		category = ErrNotFound
	case "conflict":
		category = ErrConflict
	case "unauthorized":
		category = ErrUnauthorized
	}
	return &Error{Kind: category, Message: message, Cause: cause}
}

func newError(kind error, message string) error { return &Error{Kind: kind, Message: message} }

// IsKind reports whether err belongs to the requested domain category.
func IsKind(err, kind error) bool { return errors.Is(err, kind) }
